      hullRadius: p.hullRadius,
      combatRadius: p.combatRadius,
      movementIntent: { x: 0, y: 0 },
      moveSpeed: p.moveSpeed,
      alive: true,
      attackDamage: copyWire(p.attackDamage),
      attackReach: p.attackReach,
      attackReachMode: p.attackReachMode,
